{"command":"python3 -c "
for mod in ['scipy', 'soundfile', 'wave', 'struct', 'json', 'subprocess']:
    try:
        __import__(mod)
        print(mod, 'is available')
    except ImportError:
        print(mod, 'NOT available')
""}

